import {DatabaseSync} from 'node:sqlite';
import {readFileSync,readdirSync} from 'node:fs';
export function integrationDB(){const sql=new DatabaseSync(':memory:');for(const file of readdirSync(new URL('../../migrations/',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())sql.exec(readFileSync(new URL('../../migrations/'+file,import.meta.url),'utf8'));return {sql,prepare(text){let values=[];return {bind(...v){values=v;return this;},async first(){return sql.prepare(text).get(...values)||null;},async all(){return {results:sql.prepare(text).all(...values)};},async run(){if(/RETURNING/i.test(text))return {results:sql.prepare(text).all(...values)};const r=sql.prepare(text).run(...values);return {meta:{changes:Number(r.changes)}};}};},async batch(list){sql.exec('BEGIN');try{const out=[];for(const s of list)out.push(await s.run());sql.exec('COMMIT');return out;}catch(error){sql.exec('ROLLBACK');throw error;}}};}
